import type { MediaKind } from '@downora/types';

export interface Sample {
  label: string;
  path: string;
  kind: MediaKind;
}

/**
 * Original sample files bundled with the app (generated by
 * scripts/generate-samples.sh). They are real files served by this origin, so
 * analysing and saving them exercises the full engine.
 */
export const SAMPLES: Sample[] = [
  { label: '1080p MP4', path: '/samples/downora-sample-1080p.mp4', kind: 'video' },
  { label: '720p WebM', path: '/samples/downora-sample-720p.webm', kind: 'video' },
  { label: 'MP3', path: '/samples/downora-sample-tone.mp3', kind: 'audio' },
  { label: 'M4A', path: '/samples/downora-sample-tone.m4a', kind: 'audio' },
  { label: 'WAV', path: '/samples/downora-sample-tone.wav', kind: 'audio' },
];

export function sampleUrl(sample: Sample): string {
  // Resolve against the app's base so the samples also work under a sub-path.
  return new URL(`${import.meta.env.BASE_URL}${sample.path.slice(1)}`, window.location.href).href;
}
